import sys

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    strings = data[1:1+n]

    left = {}
    right = {}

    for s in strings:
        bal = 0
        mn = 0
        for ch in s:
            if ch == 40:
                bal += 1
            else:
                bal -= 1
            if bal < mn:
                mn = bal

        if mn >= 0:
            if bal >= 0:
                left[bal] = left.get(bal, 0) + 1
            continue

        bal2 = 0
        mn2 = 0
        for ch in reversed(s):
            if ch == 41:
                bal2 += 1
            else:
                bal2 -= 1
            if bal2 < mn2:
                mn2 = bal2

        if mn2 >= 0:
            right[bal2] = right.get(bal2, 0) + 1

    ans = 0
    for b, cnt in left.items():
        if b in right:
            ans += min(cnt, right[b])

    print(ans)

if __name__ == "__main__":
    solve()
